import{_ as a,o as n,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Deployment","description":"","frontmatter":{"title":"Deployment"},"headers":[],"relativePath":"deployment/index.md","filePath":"deployment/index.md"}'),s={name:"deployment/index.md"};function r(l,e,d,i,p,h){return n(),t("div",null,[...e[0]||(e[0]=[o('<blockquote><p>🚧 Wingport is in active development. The API described here is the v0.1 design. Star the repo to follow along, or join the early access list.</p></blockquote><h1 id="deployment" tabindex="-1">Deployment <a class="header-anchor" href="#deployment" aria-label="Permalink to &quot;Deployment&quot;">​</a></h1><h2 id="supabase-v0-1" tabindex="-1">Supabase (v0.1) <a class="header-anchor" href="#supabase-v0-1" aria-label="Permalink to &quot;Supabase (v0.1)&quot;">​</a></h2><p>Covered in <a href="/installation">Installation</a>. <code>wingport deploy</code> = migrate + deploy function. Redeploying updates the gateway in place; config changes take effect on deploy.</p><p><strong>Runtime notes:</strong> the gateway is stateless — all state lives in Postgres — so it scales with Supabase&#39;s edge runtime. Long generations are bounded by edge function wall-clock limits; the SDK&#39;s chunk-timeout and retry semantics are designed around this, and streaming responses are unaffected in typical use.</p><h2 id="firebase-planned" tabindex="-1">Firebase <span class="VPBadge warning">Planned</span> <a class="header-anchor" href="#firebase-planned" aria-label="Permalink to &quot;Firebase &lt;span class=&quot;VPBadge warning&quot;&gt;Planned&lt;/span&gt;&quot;">​</a></h2><p>Cloud Functions target with Firebase Auth verification and Firestore-backed metering.</p><h2 id="self-hosted-dart-shelf-planned" tabindex="-1">Self-hosted Dart (Shelf) <span class="VPBadge warning">Planned</span> <a class="header-anchor" href="#self-hosted-dart-shelf-planned" aria-label="Permalink to &quot;Self-hosted Dart (Shelf) &lt;span class=&quot;VPBadge warning&quot;&gt;Planned&lt;/span&gt;&quot;">​</a></h2><p>A pure-Dart gateway for teams running Dart on the server (Shelf/Dart Frog/Serverpod) — one language end to end.</p><h2 id="wingport-cloud-planned" tabindex="-1">Wingport Cloud <span class="VPBadge warning">Planned</span> <a class="header-anchor" href="#wingport-cloud-planned" aria-label="Permalink to &quot;Wingport Cloud &lt;span class=&quot;VPBadge warning&quot;&gt;Planned&lt;/span&gt;&quot;">​</a></h2><p>The hosted option for teams who don&#39;t want to manage even a config file: managed gateway, key vault, team dashboard, and a managed-keys mode where you skip provider signups entirely and are billed per token. The open-source core remains the foundation — Cloud runs the same code you can read.</p><hr>',12)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
